val readers: Map[String, Decoder[_ <: Event]] = Map(
  "order-created" -> Decoder[OrderCreated],
  "order-shipped" -> Decoder[OrderShipped],
)
val token = record.headers().lastHeader("content-type").value().map(_.toChar).mkString
readers.get(token) match {
  case Some(d) => d.asInstanceOf[Decoder[Event]].decodeJson(parse(record.value()))
  case None    => Left(UnknownToken(token))    // fail fast, never trial-decode
}
